export const SUBS: SubV5[] = [{"s":177,"e":215,"hold_to":227,"who":"NELEH","shown":"BLUEPRINT FIGURE","text":"Three of us stepped down this year.","kind":"dialogue","mode":"on-mic","id":"a5-25-01","os":false},{"s":236,"e":306,"hold_to":318,"who":"NELEH","shown":"BLUEPRINT FIGURE","text":"Leave out Mas and Gerg, and the four of us are a majority.","kind":"dialogue","mode":"on-mic","id":"a5-25-02","os":false},{"s":320,"e":401,"hold_to":413,"who":"NELEH","shown":"NELEH","text":"This board controls the company. Not the other way round.","kind":"dialogue","mode":"on-mic","id":"a5-25-03","os":false},{"s":433,"e":531,"hold_to":543,"who":"NELEH","shown":"NELEH","text":"Our biggest investor has put in billions. It gets this many votes.","kind":"dialogue","mode":"on-mic","id":"a5-25-04","os":false},{"s":545,"e":591,"hold_to":603,"who":"NELEH","shown":"NELEH","text":"And the CEO? What does he own?","kind":"dialogue","mode":"on-mic","id":"a5-25-05","os":false},{"s":609,"e":631,"hold_to":643,"who":"MADA","shown":"MADA","text":"Good question.","kind":"dialogue","mode":"on-mic","id":"a5-25-06","os":false},{"s":1135,"e":1154,"hold_to":1166,"who":"MAS","shown":"MAS","text":"super.","kind":"dialogue","mode":"on-mic","id":"a5-26-01","os":false},{"s":1216,"e":1263,"hold_to":1275,"who":"MAS","shown":"MAS","text":"i don't keep score.","kind":"vo","mode":"on-mic","id":"a5-26a-01","os":false},{"s":1569,"e":1736,"hold_to":1748,"who":"ALYI","shown":"ALYI","text":"Mas. The board has decided that you will no longer lead the company. It will be announced shortly.","kind":"dialogue","mode":"call","id":"a5-27-01","os":false},{"s":1766,"e":1811,"hold_to":1823,"who":"ALYI","shown":"ALYI","text":"Do you have any questions?","kind":"dialogue","mode":"call","id":"a5-27-02","os":false},{"s":1846,"e":1877,"hold_to":1888,"who":"NELEH","shown":"NELEH","text":"Is his feed frozen?","kind":"dialogue","mode":"on-mic","id":"a5-27-03","os":false},{"s":1888,"e":1953,"hold_to":1965,"who":"ALYI","shown":"ALYI","text":"No. That is just him.","kind":"dialogue","mode":"call","id":"a5-27-04","os":false},{"s":2004,"e":2023,"hold_to":2035,"who":"MAS","shown":"MAS","text":"super.","kind":"dialogue","mode":"speaker","id":"a5-27-05","os":true},{"s":2110,"e":2175,"hold_to":2186,"who":"NELEH","shown":"NELEH","text":"Step two. I'll read it once before it goes up.","kind":"dialogue","mode":"on-mic","id":"a5-27-06","os":false},{"s":2186,"e":2403,"hold_to":2415,"who":"NELEH","shown":"NELEH","text":"…he was not consistently candid in his communications with the board… The board no longer has confidence in his ability to continue leading NopeAI.","kind":"dialogue","mode":"on-mic","id":"a5-27-07","os":false},{"s":2419,"e":2444,"hold_to":2456,"who":"NELEH","shown":"NELEH","text":"Any objections?","kind":"dialogue","mode":"on-mic","id":"a5-27-08","os":false},{"s":2516,"e":2631,"hold_to":2642,"who":"NELEH","shown":"NELEH","text":"Step three. Rima, thank you for agreeing to serve as interim CEO while we search.","kind":"dialogue","mode":"on-mic","id":"a5-27-09","os":false},{"s":2642,"e":2661,"hold_to":2670,"who":"RIMA","shown":"RIMA","text":"For how long?","kind":"dialogue","mode":"call","id":"a5-27-10","os":false},{"s":2670,"e":2700,"hold_to":2712,"who":"NELEH","shown":"NELEH","text":"Until the search is done.","kind":"dialogue","mode":"on-mic","id":"a5-27-11","os":false},{"s":2716,"e":2783,"hold_to":2794,"who":"ALYI","shown":"ALYI","text":"The staff will ask you what happened.","kind":"dialogue","mode":"call","id":"a5-27-12","os":false},{"s":2794,"e":2822,"hold_to":2833,"who":"RIMA","shown":"RIMA","text":"What should I tell them?","kind":"dialogue","mode":"call","id":"a5-27-13","os":false},{"s":2833,"e":2904,"hold_to":2916,"who":"NELEH","shown":"NELEH","text":"What the post says. That's all the board is saying for now.","kind":"dialogue","mode":"on-mic","id":"a5-27-14","os":false},{"s":2919,"e":2945,"hold_to":2957,"who":"RIMA","shown":"RIMA","text":"We'll share more soon.","kind":"dialogue","mode":"call","id":"a5-27-15","os":false},{"s":2959,"e":2975,"hold_to":2986,"who":"NELEH","shown":"NELEH","text":"Will we?","kind":"dialogue","mode":"on-mic","id":"a5-27-16","os":false},{"s":2986,"e":3017,"hold_to":3029,"who":"RIMA","shown":"RIMA","text":"More. Soon.","kind":"dialogue","mode":"call","id":"a5-27-17","os":true},{"s":3062,"e":3122,"hold_to":3134,"who":"EMPLOYEE","shown":"EMPLOYEE","text":"Is this a coup? Because it looks like one.","kind":"dialogue","mode":"on-mic","id":"a5-27-18","os":false},{"s":3145,"e":3334,"hold_to":3346,"who":"ALYI","shown":"ALYI","text":"You can call it this way… I disagree with this. This was the board doing its duty to the mission of the nonprofit…","kind":"dialogue","mode":"on-mic","id":"a5-27-19","os":false},{"s":3381,"e":3628,"hold_to":3628,"who":"GERG","shown":"GERG","text":"…I quit.","kind":"post","mode":"post","id":"a5-27-P1","os":false},{"s":3424,"e":3519,"hold_to":3531,"who":"NELEH","shown":"NELEH","text":"Nobody asked him to go. He'd have kept his job, just not the chair.","kind":"dialogue","mode":"on-mic","id":"a5-27-20","os":false},{"s":3537,"e":3604,"hold_to":3616,"who":"ALYI","shown":"ALYI","text":"Gerg has never waited to be asked.","kind":"dialogue","mode":"call","id":"a5-27-21","os":false},{"s":3649,"e":3743,"hold_to":3743,"who":"MAS","shown":"MAS","text":"…sorta like reading your own eulogy while you're still alive","kind":"post","mode":"post","id":"a5-27-P2","os":false},{"s":3774,"e":3935,"hold_to":3947,"who":"NELEH","shown":"NELEH","text":"They're all asking whether it was allowed. It was. The charter, footnote three. I've read it four times tonight.","kind":"dialogue","mode":"on-mic","id":"a5-27-22","os":false},{"s":3967,"e":4098,"hold_to":4110,"who":"NELEH","shown":"NELEH","text":"What they actually want to know is what happens on Monday. I'd like to be able to tell them something.","kind":"dialogue","mode":"on-mic","id":"a5-27-23","os":false},{"s":4119,"e":4186,"hold_to":4192,"who":"ALYI","shown":"ALYI","text":"Step four will reveal itself.","kind":"dialogue","mode":"on-mic","id":"a5-27-24","os":false},{"s":4192,"e":4205,"hold_to":4217,"who":"NELEH","shown":"NELEH","text":"When?","kind":"dialogue","mode":"on-mic","id":"a5-27-25","os":false},{"s":4218,"e":4268,"hold_to":4280,"who":"ALYI","shown":"ALYI","text":"The company will tell us.","kind":"dialogue","mode":"on-mic","id":"a5-27-26","os":false},{"s":4282,"e":4389,"hold_to":4401,"who":"NELEH","shown":"NELEH","text":"That isn't a time, Alyi. All we've given the staff since yesterday is more soon.","kind":"dialogue","mode":"on-mic","id":"a5-27-27","os":false},{"s":4414,"e":4478,"hold_to":4490,"who":"ALYI","shown":"ALYI","text":"That is the company telling us.","kind":"dialogue","mode":"on-mic","id":"a5-27-28","os":false},{"s":4530,"e":4569,"hold_to":4581,"who":"NELEH","shown":"NELEH","text":"Then we'll write step four ourselves.","kind":"dialogue","mode":"on-mic","id":"a5-27-29","os":false},{"s":4683,"e":4887,"hold_to":4899,"who":"NELEH","shown":"NELEH","text":"Mario, it's Neleh, from the NopeAI board. I'll be direct. The board is offering you the job of CEO, and it wants to discuss a merger.","kind":"dialogue","mode":"on-mic","id":"a5-27-30","os":false},{"s":4900,"e":5084,"hold_to":5084,"who":"MARIO","shown":"MARIO","text":"Neleh, hi. Wow. I've actually written up some thoughts on exactly this. Eleven pages, on the conditions under which we might, hypothetically—","kind":"dialogue","mode":"on-mic","id":"a5-27-31","os":false},{"s":5075,"e":5113,"hold_to":5125,"who":"ADELINA","shown":"ADELINA","text":"In plain English: no.","kind":"dialogue","mode":"on-mic","id":"a5-27-32","os":false},{"s":5160,"e":5203,"hold_to":5209,"who":"ADELINA","shown":"ADELINA","text":"It's Nozama. About the money.","kind":"dialogue","mode":"on-mic","id":"a5-27-33","os":false},{"s":5209,"e":5261,"hold_to":5273,"who":"MARIO","shown":"MARIO","text":"Hi. Yes. We're very worried. How much?","kind":"dialogue","mode":"on-mic","id":"a5-27-34","os":false},{"s":5311,"e":5661,"hold_to":5661,"who":"MAS","shown":"MAS","text":"first and last time i ever wear one of these","kind":"post","mode":"post","id":"a5-27-P3","os":false},{"s":5368,"e":5499,"hold_to":5511,"who":"NELEH","shown":"NELEH","text":"He's been in the building for hours. We've talked all day about him coming back, and we're no closer.","kind":"dialogue","mode":"on-mic","id":"a5-27-35","os":false},{"s":5514,"e":5563,"hold_to":5574,"who":"ALYI","shown":"ALYI","text":"They gave him a guest badge.","kind":"dialogue","mode":"on-mic","id":"a5-27-36","os":false},{"s":5574,"e":5633,"hold_to":5645,"who":"NELEH","shown":"NELEH","text":"It's the correct badge. He doesn't work here.","kind":"dialogue","mode":"on-mic","id":"a5-27-37","os":false},{"s":5776,"e":5835,"hold_to":5844,"who":"NELEH","shown":"NELEH","text":"Ttemme, we'd like you to serve as interim CEO.","kind":"dialogue","mode":"on-mic","id":"a5-27-38","os":false},{"s":5844,"e":5885,"hold_to":5897,"who":"TTEMME","shown":"TTEMME","text":"You already have an interim CEO.","kind":"dialogue","mode":"on-mic","id":"a5-27-39","os":false},{"s":5898,"e":5927,"hold_to":5939,"who":"NELEH","shown":"NELEH","text":"We'd like a different one.","kind":"dialogue","mode":"on-mic","id":"a5-27-40","os":false},{"s":5943,"e":6031,"hold_to":6043,"who":"TTEMME","shown":"TTEMME","text":"Fine. But before I say yes, I need to know why you fired him.","kind":"dialogue","mode":"on-mic","id":"a5-27-41","os":false},{"s":6102,"e":6117,"hold_to":6129,"who":"TTEMME","shown":"TTEMME","text":"Okay.","kind":"dialogue","mode":"on-mic","id":"a5-27-42","os":false},{"s":6147,"e":6181,"hold_to":6193,"who":"TTEMME","shown":"TTEMME","text":"Chat… for how long?","kind":"dialogue","mode":"on-mic","id":"a5-27-43","os":false},{"s":6336,"e":6400,"hold_to":6408,"who":"TASYA","shown":"TASYA","text":"Good evening. You'll want to hear our statement.","kind":"dialogue","mode":"on-mic","id":"a5-27-44","os":false},{"s":6408,"e":6742,"hold_to":6754,"who":"TASYA","shown":"TASYA","text":"We look forward to getting to know Ttemme and NopeAI's new leadership team and working with them. And we're extremely excited to share the news that Mas Manalt and Gerg Mockbran, together with colleagues, will be joining Macrosoft to lead a new advanced AI research team.","kind":"dialogue","mode":"on-mic","id":"a5-27-45","os":false},{"s":6848,"e":6866,"hold_to":6878,"who":"NELEH","shown":"NELEH","text":"Step four?","kind":"dialogue","mode":"on-mic","id":"a5-27-46","os":true},{"s":7051,"e":7143,"hold_to":7143,"who":"RIMA","shown":"RIMA","text":"NopeAI is nothing without its people","kind":"post","mode":"post","id":"a5-29-P1","os":false},{"s":7167,"e":7202,"hold_to":7214,"who":"MAS","shown":"MAS","text":"the badge was a joke.","kind":"dialogue","mode":"on-mic","id":"a5-29-01","os":false},{"s":7225,"e":7246,"hold_to":7258,"who":"MAS","shown":"MAS","text":"mostly.","kind":"dialogue","mode":"on-mic","id":"a5-29-02","os":false},{"s":7302,"e":7356,"hold_to":7364,"who":"GERG","shown":"GERG","text":"Sorry, one sec. I've got a build compiling.","kind":"dialogue","mode":"call","id":"a5-29-03","os":false},{"s":7364,"e":7404,"hold_to":7410,"who":"MAS","shown":"MAS","text":"it's two in the morning, gerg.","kind":"dialogue","mode":"on-mic","id":"a5-29-04","os":false},{"s":7410,"e":7599,"hold_to":7611,"who":"GERG","shown":"GERG","text":"Best time there is. Nobody else is pushing anything. Anyway, that's not why I called. You've got the staff letter open? Scroll down.","kind":"dialogue","mode":"call","id":"a5-29-05","os":false},{"s":7629,"e":7792,"hold_to":7803,"who":"GERG","shown":"GERG","text":"They're telling the board they're \"…unable to work for or with people that lack competence, judgment and care for our mission and employees.\"","kind":"dialogue","mode":"call","id":"a5-29-06","os":false},{"s":7803,"e":7870,"hold_to":7879,"who":"GERG","shown":"GERG","text":"And they'll quit, \"…unless all current board members resign…\"","kind":"dialogue","mode":"call","id":"a5-29-07","os":false},{"s":7879,"e":7913,"hold_to":7920,"who":"MAS","shown":"MAS","text":"and go to macrosoft.","kind":"dialogue","mode":"on-mic","id":"a5-29-08","os":false},{"s":7920,"e":8011,"hold_to":8023,"who":"GERG","shown":"GERG","text":"Yep. Macrosoft's promised them \"…positions for all NopeAI employees…\"","kind":"dialogue","mode":"call","id":"a5-29-09","os":false},{"s":8024,"e":8058,"hold_to":8067,"who":"MAS","shown":"MAS","text":"that's a lot of desks.","kind":"dialogue","mode":"on-mic","id":"a5-29-10","os":false},{"s":8067,"e":8090,"hold_to":8102,"who":"GERG","shown":"GERG","text":"Scroll to the bottom.","kind":"dialogue","mode":"call","id":"a5-29-11","os":false},{"s":8127,"e":8145,"hold_to":8157,"who":"GERG","shown":"GERG","text":"Alyi signed it.","kind":"dialogue","mode":"call","id":"a5-29-12","os":false},{"s":8164,"e":8191,"hold_to":8202,"who":"MAS","shown":"MAS","text":"alyi voted.","kind":"dialogue","mode":"on-mic","id":"a5-29-13","os":false},{"s":8202,"e":8220,"hold_to":8232,"who":"GERG","shown":"GERG","text":"He did both.","kind":"dialogue","mode":"call","id":"a5-29-14","os":true},{"s":8272,"e":8348,"hold_to":8360,"who":"GERG","shown":"GERG","text":"That'll be the share sale. Everybody's been waiting on that one.","kind":"dialogue","mode":"call","id":"a5-29-15","os":true},{"s":8395,"e":8425,"hold_to":8434,"who":"MAS","shown":"MAS","text":"what are you building?","kind":"dialogue","mode":"on-mic","id":"a5-29-16","os":false},{"s":8434,"e":8486,"hold_to":8498,"who":"GERG","shown":"GERG","text":"The company. Again. Just in case.","kind":"dialogue","mode":"call","id":"a5-29-17","os":false},{"s":8528,"e":8572,"hold_to":8584,"who":"GERG","shown":"GERG","text":"So. Do I tell everyone to pack?","kind":"dialogue","mode":"call","id":"a5-29-18","os":false},{"s":8592,"e":8632,"hold_to":8644,"who":"MAS","shown":"MAS","text":"ask me when it compiles.","kind":"dialogue","mode":"on-mic","id":"a5-29-19","os":true},{"s":8703,"e":8791,"hold_to":8803,"who":"TASYA","shown":"TASYA","text":"Don't get up, Mas. I won't keep you. Everyone is welcome.","kind":"dialogue","mode":"on-mic","id":"a5-29-20","os":true},{"s":8807,"e":8828,"hold_to":8839,"who":"MAS","shown":"MAS","text":"everyone.","kind":"dialogue","mode":"on-mic","id":"a5-29-21","os":false},{"s":8839,"e":8920,"hold_to":8932,"who":"TASYA","shown":"TASYA","text":"Yes. You first. And there's a desk for every one of them.","kind":"dialogue","mode":"on-mic","id":"a5-29-22","os":true},{"s":8945,"e":8971,"hold_to":8983,"who":"MAS","shown":"MAS","text":"leave it open.","kind":"dialogue","mode":"on-mic","id":"a5-29-23","os":false},{"s":9198,"e":9230,"hold_to":9242,"who":"NELEH","shown":"NELEH","text":"Has anyone read the char—","kind":"dialogue","mode":"call","id":"a5-29-24","os":false},{"s":9400,"e":9539,"hold_to":9539,"who":"ALYI","shown":"ALYI","text":"I deeply regret my participation in the board's actions. I never intended to harm NopeAI…","kind":"post","mode":"post","id":"a5-30-P1","os":false},{"s":9572,"e":9604,"hold_to":9616,"who":"ALYI","shown":"ALYI","text":"You sent three.","kind":"dialogue","mode":"on-mic","id":"a5-30-01","os":false},{"s":9619,"e":9650,"hold_to":9662,"who":"MAS","shown":"MAS","text":"one for each day.","kind":"dialogue","mode":"on-mic","id":"a5-30-02","os":false},{"s":9668,"e":9713,"hold_to":9724,"who":"ALYI","shown":"ALYI","text":"It has been four days.","kind":"dialogue","mode":"on-mic","id":"a5-30-03","os":false},{"s":9724,"e":9761,"hold_to":9773,"who":"MAS","shown":"MAS","text":"i'm not counting today.","kind":"dialogue","mode":"on-mic","id":"a5-30-04","os":false},{"s":9864,"e":9929,"hold_to":9941,"who":"MAS","shown":"MAS","text":"what happens to you if nopeai disappears?","kind":"dialogue","mode":"on-mic","id":"a5-30-05","os":false},{"s":9943,"e":10123,"hold_to":10135,"who":"TASYA","shown":"TASYA","text":"Oh, we'd be fine. …we have all the IP rights and all the capability… We are below them, above them, around them.","kind":"dialogue","mode":"on-mic","id":"a5-30-06","os":false},{"s":10168,"e":10184,"hold_to":10196,"who":"TASYA","shown":"TASYA","text":"Hello.","kind":"dialogue","mode":"on-mic","id":"a5-30-07","os":true},{"s":10335,"e":10374,"hold_to":10386,"who":"TERB","shown":"TERB","text":"Which room is on fire?","kind":"dialogue","mode":"on-mic","id":"a5-30-08","os":false},{"s":10411,"e":10427,"hold_to":10439,"who":"TERB","shown":"TERB","text":"…Ah.","kind":"dialogue","mode":"on-mic","id":"a5-30-09","os":false},{"s":10460,"e":10738,"hold_to":10750,"who":"TERB","shown":"TERB","text":"Before this goes out, I'm reading it once, so nobody's surprised. We have reached an agreement in principle for Mas Manalt to return to NopeAI as CEO with a new initial board of Terb (Chair), the Other Yrral, and Mada.","kind":"dialogue","mode":"on-mic","id":"a5-30-10","os":false},{"s":10758,"e":10781,"hold_to":10793,"who":"MAS","shown":"MAS","text":"you're staying?","kind":"dialogue","mode":"on-mic","id":"a5-30-11","os":false},{"s":10802,"e":10869,"hold_to":10880,"who":"TERB","shown":"TERB","text":"He stays. You and Gerg don't sit on the board.","kind":"dialogue","mode":"on-mic","id":"a5-30-12","os":false},{"s":10880,"e":10902,"hold_to":10911,"who":"MAS","shown":"MAS","text":"we'll stand.","kind":"dialogue","mode":"on-mic","id":"a5-30-13","os":false},{"s":10911,"e":10965,"hold_to":10976,"who":"TERB","shown":"TERB","text":"And there'll be an independent review.","kind":"dialogue","mode":"on-mic","id":"a5-30-14","os":false},{"s":10976,"e":10995,"hold_to":11007,"who":"MAS","shown":"MAS","text":"of what?","kind":"dialogue","mode":"on-mic","id":"a5-30-15","os":false},{"s":11033,"e":11055,"hold_to":11067,"who":"MADA","shown":"MADA","text":"Good question.","kind":"dialogue","mode":"on-mic","id":"a5-30-16","os":false},{"s":11076,"e":11100,"hold_to":11112,"who":"MAS","shown":"MAS","text":"good question.","kind":"dialogue","mode":"on-mic","id":"a5-30-17","os":false},{"s":11181,"e":11258,"hold_to":11258,"who":"GERG","shown":"GERG","text":"Returning to NopeAI & getting back to coding tonight.","kind":"post","mode":"post","id":"a5-30-P2","os":false},{"s":11279,"e":11385,"hold_to":11385,"who":"TTEMME","shown":"TTEMME","text":"I am deeply pleased by this result, after ~72 very intense hours of work.","kind":"post","mode":"post","id":"a5-30-P3","os":false},{"s":11392,"e":11424,"hold_to":11436,"who":"TTEMME","shown":"TTEMME","text":"Chat, we're so back.","kind":"dialogue","mode":"on-mic","id":"a5-30-18","os":true},{"s":11662,"e":11681,"hold_to":11693,"who":"MAS","shown":"MAS","text":"okay.","kind":"dialogue","mode":"on-mic","id":"a5-30-19","os":false},{"s":11793,"e":11809,"hold_to":11818,"who":"GERG","shown":"GERG","text":"Is it ready?","kind":"dialogue","mode":"on-mic","id":"a5-31-01","os":false},{"s":11818,"e":11847,"hold_to":11858,"who":"MAS","shown":"MAS","text":"it's a preview.","kind":"dialogue","mode":"on-mic","id":"a5-31-02","os":false},{"s":11858,"e":11889,"hold_to":11901,"who":"GERG","shown":"GERG","text":"You said that about the last one.","kind":"dialogue","mode":"on-mic","id":"a5-31-03","os":false},{"s":12047,"e":12273,"hold_to":12285,"who":"MAS","shown":"MAS","text":"i love and respect alyi, i think he's a guiding light of the field and a gem of a human being. i harbor zero ill will towards him.","kind":"dialogue","mode":"on-mic","id":"a5-31-04","os":false}];
